def _load_embedded(name: str, packed: str):
    m = _types.ModuleType(name)
    m.__file__ = f"<{name}:embedded>"
    src = _zlib.decompress(_b64.b85decode(packed.encode("ascii"))).decode("utf-8")
    exec(compile(src, m.__file__, "exec"), m.__dict__)
    return m

